const job = $json.job_opening || {};
const skills = Array.isArray($json.approved_skills) ? $json.approved_skills : [];
const candidate = $json.candidate || {};

const text = [
  job.title,
  job.department,
  job.description,
  ...(Array.isArray(job.responsibilities) ? job.responsibilities : []),
  ...(Array.isArray(job.qualifications) ? job.qualifications : []),
  ...(Array.isArray(job.keywords) ? job.keywords : []),
  ...skills.map(s => s.skill_name || s.name || '')
].filter(Boolean).join(' ').toLowerCase();

const technicalKeywords = [
  'software','developer','engineer','frontend','backend','full stack','fullstack','react','next.js','node','typescript','javascript','java','python','django','spring','api','rest','graphql','database','sql','postgres','mongodb','devops','aws','azure','gcp','cloud','docker','kubernetes','terraform','ci/cd','machine learning','ml','ai','data scientist','data engineer','data analyst','analytics','power bi','tableau','qa','quality assurance','tester','testing','automation testing','manual testing','sdet','cybersecurity','security','network','system admin','it support','technical support','implementation','solutions engineer','product engineer','site reliability','sre','mobile','android','ios','flutter','react native','web development','architecture','microservices'
];

const technicalAdjacentKeywords = [
  'business analyst','technical analyst','product owner','product manager','scrum master','project manager','implementation consultant','erp consultant','crm consultant','solution consultant','pre sales engineer','technical writer','manual qa','uat','support analyst','application support','functional consultant','systems analyst'
];

const nonTechnicalKeywords = [
  'marketing','sales','business development','hr','human resources','recruiter','talent acquisition','finance','accounting','admin','operations','customer success','customer support','content','seo','copywriter','designer','graphic','social media','brand','legal','procurement','office manager','delivery partner','driver','logistics','warehouse','field sales','retail','b2b sales','inside sales'
];

const hasAny = (arr) => arr.some(k => text.includes(k));
let role_category = 'non_technical';
let role_subtype = 'business_non_technical';

if (hasAny(technicalKeywords)) {
  role_category = 'technical';
  role_subtype = 'core_technical';
}

if (hasAny(technicalAdjacentKeywords)) {
  role_category = 'technical';
  role_subtype = 'technical_adjacent_non_coding';
}

if (hasAny(nonTechnicalKeywords) && !hasAny(technicalKeywords) && !hasAny(technicalAdjacentKeywords)) {
  role_category = 'non_technical';
  role_subtype = 'business_non_technical';
}

if (text.includes('technical recruiter') || text.includes('it recruiter') || text.includes('tech recruiter')) {
  role_category = 'non_technical';
  role_subtype = 'recruitment_hr';
}

const role_detection = {
  role_category,
  role_subtype,
  detection_basis: {
    job_title: job.title || '',
    department: job.department || '',
    weighted_skills: skills.map(s => s.skill_name || s.name || '').filter(Boolean),
    rule: role_category === 'technical'
      ? 'Technical or technical-adjacent role detected from job title/skills/description.'
      : 'Business/non-technical role detected from job title/skills/description.'
  }
};

return {
  json: {
    ...$json,
    role_detection,
    role_category,
    role_subtype
  }
};

const c = $json.candidate || {};
const job = $json.job_opening || {};
const skills = Array.isArray($json.approved_skills) ? $json.approved_skills : [];
const resumeText = (c.resume_text || '').slice(0, 7000);

const prompt = `You are a senior technical recruitment screening assistant.

Role category: ${job.category || 'technical'}
Role subtype: ${job.sub_category || 'core_technical'}

Evaluate how well this candidate matches the job opening based mainly on resume_text and weighted skills.

Technical scoring rules:
- Score primarily from resume_text and actual project/work evidence.
- candidate.skills may be incomplete or outdated. Do not over-rely on candidate.skills.
- For core technical roles, give strong credit for direct evidence of tools, frameworks, languages, architecture, production work, deployments, APIs, databases, cloud, testing, data/ML, security, or engineering ownership.
- For technical-adjacent or non-coding technical roles such as Business Analyst, Product Owner, Implementation Consultant, Technical Support, Manual QA, UAT, Solution Consultant, ERP/CRM Consultant, or Technical Writer:
  - Do NOT penalize the candidate for lack of coding unless coding is explicitly required.
  - Score domain understanding, tools, workflows, documentation, stakeholder communication, implementation exposure, support experience, QA/UAT, requirements analysis, and technical coordination.
- If the candidate has less experience than required, reduce fuzzy_score proportionally, but do not set all skill scores to 0 when skill evidence exists.
- Score each weighted skill from 0 to 100.
- Compute fuzzy_score as weighted sum of skill scores using the provided weights.
- recommendation must be "shortlist" only if fuzzy_score >= ${$json.match_threshold || 60}, otherwise "reject".
- Return only valid JSON.

Weighted skills:
${JSON.stringify(skills, null, 2)}

Job opening:
${JSON.stringify(job, null, 2)}

Candidate structured profile:
${JSON.stringify({
  candidate_id: c.candidate_id,
  full_name: c.full_name,
  email: c.email,
  skills: c.skills,
  experience_years: c.experience_years,
  source: c.source
}, null, 2)}

Resume text:
${resumeText}

Return ONLY valid JSON in this exact format:
{
  "fuzzy_score": 0,
  "skill_scores": [
    {
      "skill_name": "string",
      "weight": 0.3,
      "score": 0,
      "evidence": "short evidence from resume"
    }
  ],
  "match_reason": "brief recruiter-facing explanation",
  "strengths": ["string"],
  "skill_gaps": ["string"],
  "recommendation": "shortlist"
}

No markdown. No code fences. No explanation outside JSON.`;

return { json: { ...$json, prompt } };

