// 1. Get original candidate and job details from the classification node
const originalData = $('Code - Classify Role Category').item.json;

// 2. Extract output string from the AI Agent node
const aiOutput = $json.output || $json.text || $json.response || $json.message;

if (!aiOutput) {
  throw new Error('AI Agent returned empty output');
}

// 3. Robust JSON parser helper
function parseJson(value) {
  if (typeof value === 'object' && value !== null) return value;

  let text = String(value || '').trim();
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

let parsed;
try {
  parsed = parseJson(aiOutput);
} catch (err) {
  parsed = {
    fuzzy_score: 0,
    skill_scores: [],
    match_reason: 'Failed to parse AI output: ' + err.message,
    strengths: [],
    skill_gaps: [],
    recommendation: 'reject'
  };
}

const is_shortlisted = 
  parsed.recommendation === 'shortlist' || 
  (Number(parsed.fuzzy_score || 0) >= Number(originalData.match_threshold || 60));

return {
  json: {
    ...originalData,
    ...parsed,
    is_shortlisted,
    fuzzy_score: Number(parsed.fuzzy_score || 0),
    skill_scores: parsed.skill_scores || [],
    match_reason: parsed.match_reason || '',
    strengths: parsed.strengths || [],
    skill_gaps: parsed.skill_gaps || [],
    recommendation: parsed.recommendation || 'reject'
  }
};
